CREATE TABLE public.movie_soundtracks (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),movie_id text NOT NULL,movie_title text NOT NULL,movie_poster text,source text NOT NULL,external_id text NOT NULL,title text NOT NULL,artist text,year integer,image_url text,kind text NOT NULL CHECK(kind IN ('album','song')),source_url text,confidence text NOT NULL DEFAULT 'verified' CHECK(confidence IN ('verified','community')),submitted_by uuid,hidden boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(movie_id,source,external_id)); GRANT SELECT,INSERT ON public.movie_soundtracks TO authenticated; GRANT ALL ON public.movie_soundtracks TO service_role; ALTER TABLE public.movie_soundtracks ENABLE ROW LEVEL SECURITY; CREATE POLICY soundtracks_read ON public.movie_soundtracks FOR SELECT TO authenticated USING(NOT hidden OR submitted_by=auth.uid()); CREATE POLICY soundtracks_community ON public.movie_soundtracks FOR INSERT TO authenticated WITH CHECK(submitted_by=auth.uid() AND confidence='community' AND hidden=false AND source='itunes');
CREATE TABLE public.soundtrack_reports (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),soundtrack_id uuid NOT NULL REFERENCES public.movie_soundtracks(id),user_id uuid NOT NULL,reason text NOT NULL CHECK(length(reason) BETWEEN 1 AND 1000),created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(soundtrack_id,user_id)); GRANT SELECT,INSERT ON public.soundtrack_reports TO authenticated; GRANT ALL ON public.soundtrack_reports TO service_role; ALTER TABLE public.soundtrack_reports ENABLE ROW LEVEL SECURITY; CREATE POLICY soundtrack_reports_read ON public.soundtrack_reports FOR SELECT TO authenticated USING(user_id=auth.uid()); CREATE POLICY soundtrack_reports_insert ON public.soundtrack_reports FOR INSERT TO authenticated WITH CHECK(user_id=auth.uid());
CREATE FUNCTION public.hide_reported_soundtrack() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF (SELECT count(*) FROM public.soundtrack_reports WHERE soundtrack_id=NEW.soundtrack_id)>=3 THEN UPDATE public.movie_soundtracks SET hidden=true WHERE id=NEW.soundtrack_id AND confidence='community'; END IF; RETURN NEW; END $$; CREATE TRIGGER soundtrack_reports_hide AFTER INSERT ON public.soundtrack_reports FOR EACH ROW EXECUTE FUNCTION public.hide_reported_soundtrack();
CREATE TABLE public.soundtrack_updates (movie_id text PRIMARY KEY,updated_at timestamptz NOT NULL DEFAULT now()); GRANT SELECT ON public.soundtrack_updates TO authenticated; GRANT ALL ON public.soundtrack_updates TO service_role; ALTER TABLE public.soundtrack_updates ENABLE ROW LEVEL SECURITY; CREATE POLICY soundtrack_updates_read ON public.soundtrack_updates FOR SELECT TO authenticated USING(true);